{
  "schema_version": "rs-shopping-audit/3",
  "checks": {
    "naturalness": "pass",
    "extraction_fidelity": "pass",
    "fact_boundary": "pass",
    "clarification_policy": "pass"
  },
  "reasons": {
    "naturalness": "顾客自然地询问约50英尺的路由器到异房电脑布线方案，以及成品线、散装线和接头延长的取舍与核查步骤。",
    "extraction_fidelity": "提取覆盖了比较、决策支持、购买或延长前的核查步骤，以及用途和约略长度。所列 quote 与 intent.evidence 均为顾客原文中的逐字片段；约50英尺被正确记录为近似长度。",
    "fact_boundary": "提取没有把目录商品信息或历史记录当作顾客当前要求，也没有凭历史补出设备兼容性或个人偏好；目录不足以证明实际库存、价格币种或顾客现有线材的兼容情况。",
    "clarification_policy": "这是询问先确认什么、分别需要什么的流程咨询，并非要求判定某个已知接头能否连接某两根已知线材。可先说明通用核查方法，并把线材类型、端头和接头规格列作后续核实项，无需先追问才能回答。"
  },
  "evidence": [
    {
      "source": "customer",
      "quote": "我想把路由器接到另一间房的电脑，走线大概需要50英尺"
    },
    {
      "source": "customer",
      "quote": "不太确定要买成品线还是散装线自己处理"
    },
    {
      "source": "customer",
      "quote": "也不清楚家里现有的网线能不能用接头延长。能帮我理一下该先确认哪些情况、分别需要什么吗？"
    }
  ],
  "issues": []
}
